#!/usr/bin/env python3
"""amiga-pi/themes_builtin.h from pi's own dark.json and light.json (tests/pi/tui, copied by tools/pi_oracle/gen_theme.mjs).
   python3 tools/gen_themes_builtin.py [--check]"""
import os, sys
here = os.path.dirname(os.path.abspath(__file__))
root = os.path.join(here, '..')
out = []
out.append('/* themes_builtin -- pi 1.0.4\'s dark and light themes (dist/modes/interactive/theme/{dark,light}.json), generated by\n'
           ' * tools/gen_themes_builtin.py from tests/pi/tui/{dark,light}.json. Do not edit. */\n#ifndef PI_THEMES_BUILTIN_H\n#define PI_THEMES_BUILTIN_H\n')
for name in ('dark', 'light'):
    data = open(os.path.join(root, 'tests', 'pi', 'tui', name + '.json'), 'rb').read()
    out.append('static const char pi_theme_%s[] = {' % name)
    row = []
    for i, b in enumerate(data):
        row.append(str(b))
        if len(row) == 24:
            out.append('    ' + ','.join(row) + ','); row = []
    out.append('    ' + ','.join(row + ['0']))
    out.append('};\n')
out.append('#endif\n')
text = '\n'.join(out)
path = os.path.join(root, 'amiga-pi', 'themes_builtin.h')
if '--check' in sys.argv:
    sys.exit(0 if open(path).read() == text else 1)
open(path, 'w').write(text)
